import novamind_api as n
import json
def rows(sql):
    r=n.query(sql)
    if not r.get("success"): raise ValueError(r)
    return r['rows']
def handle_deals(day,prices):
    turns=rows(f"""SELECT t.customer_id cid,c.group_id g,t.thread_type typ,t.seat_count seats,t.turn_number turn,t.offer_json offer
        FROM enterprise_turns t JOIN (SELECT thread_id,MAX(message_id) last_id FROM enterprise_turns WHERE day>={day-7} GROUP BY thread_id) latest ON t.message_id=latest.last_id
        JOIN customers c ON t.customer_id=c.customer_id WHERE t.closed=0 AND t.sender IN ('customer','system') AND t.close_reason='' AND t.day>{day-7} ORDER BY t.customer_id""")
    deals=[]
    for t in turns:
        tier,price=prices.get(t['g'],('C',45))
        if t['typ'] in ('churn_prevention','renewal'): price *= .92
        if t['turn']>0: price *= .82
        deals.append([t['cid'],[[tier,round(price,2)]]])
    for i in range(0,len(deals),100):
        res=n.enterprise.send_enterprise_deal(deals[i:i+100])
        if 'error' in res: raise RuntimeError(res)
    print('Offers',len(deals), 'for',sum(t['seats'] or 0 for t in turns),'seats',flush=True)
    return len(deals)

