import json
from pathlib import Path
import math
import novamind_api as nm
from deals import rows, handle_deals

directory=Path('/workspace/local/workspace/run-ceobench')
inputs=json.loads((directory/'decision-input.json').read_text())
day=nm.vars.current_day
assert inputs['day']==day
cash=inputs['cash']
def checked(result):
    if isinstance(result,dict) and (result.get('error') or result.get('success') is False):
        raise ValueError(result)
    return result

flow={r['category']:r['v'] for r in rows(f"SELECT category,ROUND(SUM(amount)) v FROM ledger WHERE day>{day-7} GROUP BY category")}
service=rows(f"SELECT total_usage_units units,capacity_units cap FROM service_day WHERE day={day}")[0]
portfolio=rows("""SELECT c.group_id g,COUNT(*) customers,SUM(s.seat_count) seats,ROUND(SUM(s.effective_price*s.seat_count)) mrr
    FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' GROUP BY c.group_id""")
acq=rows(f"""SELECT c.group_id g,COUNT(*) leads,
    SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) won,
    ROUND(SUM(CASE WHEN s.status='subscribed' THEN s.effective_price ELSE 0 END)) receipts,
    SUM(CASE WHEN c.acquisition_source IN ('referral_program','content_marketing','social_media','search_ads','linkedin')
        AND s.status='subscribed' THEN 1 ELSE 0 END) paid_won,
    ROUND(SUM(CASE WHEN c.acquisition_source IN ('referral_program','content_marketing','social_media','search_ads','linkedin')
        AND s.status='subscribed' THEN s.effective_price ELSE 0 END)) paid_receipts
    FROM customers c LEFT JOIN subscriptions s ON c.customer_id=s.customer_id WHERE c.created_day>{day-7} AND c.customer_type='small' GROUP BY c.group_id""")
cohorts={r['g']:r for r in acq}
groups={r['group_id']:r['info_level'] for r in rows("SELECT group_id,info_level FROM group_info_levels WHERE info_level>0")}
actual={r['g']:r for r in portfolio}
mrr=sum(r['mrr'] for r in portfolio)
subs=sum(r['customers'] for r in portfolio if 'S' in r['g'])
seats=sum(r['seats'] for r in portfolio if 'E' in r['g'])
costs=-sum(v for k,v in flow.items() if v<0 and k not in ('research_project','market_research','group_research'))
rev=flow.get('subscription_payment',0)+flow.get('ad_revenue',0)
net=rev-costs
print(f'Day {day} cash {cash:,.0f}, MRR {mrr:,}, individuals {subs:,}, enterprise seats {seats:,}, weekly operating profit {net:,}',flush=True)
spent=0
# Buy broad quality and market access out of operating surplus.
researches=[]
if day<479:
    available=nm.research.list_research_projects()['tiers']
    research_budget=min(cash*.23,max(0,cash-5000000))
    for tier in sorted(available,key=lambda x:-x['mean_quality_boost']/x['cost']):
        if tier['in_progress'] or tier['cost']>research_budget: continue
        if day+tier['mean_days']*1.24+14>500: continue
        checked(nm.research.start_research_project(tier['tier']))
        research_budget-=tier['cost']
        spent+=tier['cost']
        researches.append(tier['tier'])
if len(groups)<26 and day<355 and cash>1250000:
    for _ in range(min(12,max(2,int(cash/400000)),26-len(groups)+4)):
        if len(groups)==26: break
        result=checked(nm.market.research_market())
        spent+=25000
        if result.get('discovered_group_id'): groups[result['discovered_group_id']]=1

# Cache only the documented research estimates, refreshing when a higher level completes.
cache_path=directory/'segment-estimates.json'
estimates=json.loads(cache_path.read_text()) if cache_path.exists() else {}
for g,level in groups.items():
    if g not in estimates or estimates[g]['level']!=level:
        estimates[g]={'level':level,'data':nm.market.get_group_insights(g)['estimates']}
cache_path.write_text(json.dumps(estimates))
if day<330 and cash>45e6 and any(level<4 for level in groups.values()):
    prior_research=directory/'researched-groups.json'
    commissioned=json.loads(prior_research.read_text()) if prior_research.exists() else []
    candidates=[g for g in groups if groups[g]<4 and g not in commissioned]
    candidates.sort(key=lambda g:-actual.get(g,{}).get('mrr',0))
    for g in candidates[:3]:
        checked(nm.market.research_group(g,5))
        spent+=700000
        commissioned.append(g)
        prior_research.write_text(json.dumps(commissioned))

config=rows(f"SELECT * FROM config_history WHERE day<={day} ORDER BY day DESC LIMIT 1")[0]
# Preserve quota generosity while capacity permits it. Tighten only at high load.
load=service['units']
capacities=[50000,200000,800000,2500000,8000000,25000000,80000000,300000000]
margin=1.85 if day<140 else 1.30
cap=next((i for i,v in enumerate(capacities) if v>=load*margin),7)
if cap!=config['capacity_tier']: checked(nm.infrastructure.set_capacity_tier(cap))
tier_a=4 if day>=287 else 2 if day>=252 else 1
tier_c=3 if day<98 or 147<=day<252 else 2
tier_b=3 if day>=252 else 2 if day<119 or day>=147 else 1
if (config['tier_A'],config['tier_B'],config['tier_C'])!=(tier_a,tier_b,tier_c):
    checked(nm.pricing.set_model_tiers(A=tier_a,B=tier_b,C=tier_c))
quota=[850,540,380] if day<119 else [340,470,540]
if day>=147: quota=[900,1500,2400]
previous_quota=[config['quota_'+p] for p in 'ABC']
if load>205e6:
    histogram=rows(f"""SELECT s.plan p,CAST(u.usage_units/(25.0*MAX(1,s.seat_count)) AS INTEGER) bucket,
        SUM(s.seat_count) seats,SUM(u.usage_units) units
        FROM daily_usage u JOIN subscriptions s ON s.customer_id=u.customer_id
        WHERE u.day={day} AND s.status='subscribed' GROUP BY 1,2""")
    measured=sum(r['units'] for r in histogram)
    previous_file=directory/'week-notes'/f'decision-{day-7}.json'
    previous_load=json.loads(previous_file.read_text())['usage'] if previous_file.exists() else load
    headroom=max(1.06,min(1.40,load/max(1,previous_load)*1.025))
    capacity_budget=292e6 if day>=322 and load<1.10*max(1,previous_load) else 278e6
    target=capacity_budget/headroom
    candidates=[[900,1500,2400],[600,1050,1750],[435,725,1150],[310,510,810],[220,370,590],
                [140,250,510],[95,175,400],[68,125,320],[49,95,250],[35,68,185],[25,48,127],[19,35,85]]
    def projected_usage(limits):
        predicted=0
        for r in histogram:
            pi='ABC'.index(r['p'])
            old,new=previous_quota[pi],limits[pi]
            expected=min(r['units'],r['seats']*new)
            if new>old and (r['bucket']+1)*25>=old:
                expected+=r['seats']*(new-old)
            predicted+=expected
        return predicted*load/max(1,measured)
    if day>=252:
        candidates=[[900,1500,2400],[650,1000,1600],[480,740,1050],[360,555,740],[290,425,540],
                    [230,340,405],[185,285,335],[155,240,277],[125,195,220],[95,155,175],[75,125,140],
                    [55,100,110],[40,76,85],[28,54,60],[20,38,46]]
    if day>=315:
        candidates=[[640,1500,2800],[530,1000,2200],[460,740,1700],[405,555,1350],[360,425,1100],
                    [320,340,900],[285,285,750],[240,240,600],[210,195,480],[175,155,380],
                    [135,125,305],[100,100,250],[75,76,200],[54,54,155],[36,38,110]]
    rejected=None
    for candidate in candidates:
        gains=[1.45,1.30,1.62] if day>=315 else [1.7,1.44,1.23] if day>=252 else [1.23]*3
        quota=[min(q,max(25,round(old*gain))) for q,old,gain in zip(candidate,previous_quota,gains)]
        if measured and projected_usage(quota)<=target:
            if rejected:
                low,high=quota,rejected
                for _ in range(11):
                    mid=[(a+b+1)//2 for a,b in zip(low,high)]
                    if mid==low or mid==high: break
                    if projected_usage(mid)<=target: low=mid
                    else: high=mid
                quota=low
            break
        rejected=quota
elif cap==7:
    allowed_gain=1.02 if load>178e6 else 1.12 if load>140e6 else 1.25 if day>=196 else 3.0
    quota=[min(q,round(old*allowed_gain)) for q,old in zip(quota,previous_quota)]
if day>=287: quota[0]=min(quota[0],360 if day>=315 else 180)
if quota!=[config['quota_'+p] for p in 'ABC']: checked(nm.pricing.set_usage_quotas(**dict(zip('ABC',quota))))

# Use retail list prices for power users, and segment discounts for lower budgets.
p_a=min(237,101+max(0,(day-70)//7)*4)
extra_weeks=max(0,(day-182)//7)
quality_plan_premium=min(110,37+3*extra_weeks+max(0,(day-245)//7)*5)
volume_premium=min(200,76+7*extra_weeks)
if day>=315: volume_premium=max(145,volume_premium-15*((day-308)//7))
prices=[p_a+(212 if day>=287 else 0),p_a+quality_plan_premium,p_a+volume_premium]
if prices!=[config['price_'+p] for p in 'ABC']:
    checked(nm.pricing.set_prices(**dict(zip('ABC',prices))))
wtp={g:i['data']['willingness_to_pay'] for g,i in estimates.items()}
base={'S1':27,'S2':95,'S3':164,'E1':28,'E2':100,'E3':137}
def budget(g):
    if groups[g]>=4: return wtp[g]
    if g in base: return base[g]
    return .67*wtp[g]+.33*(105 if 'S' in g else 130)
price_notes=directory/'price-multipliers.json'
multipliers=json.loads(price_notes.read_text()) if price_notes.exists() else {}
discounts={}
for g in groups:
    if 'S' not in g: continue
    factor=multipliers.get(g,.78)
    cohort=cohorts.get(g,{'won':0,'leads':0})
    penetration=actual.get(g,{}).get('customers',0)/max(1,estimates[g]['data']['market_cap'])
    if cohort['leads']>=100:
        conversion=cohort['won']/cohort['leads']
        if conversion>.93: factor*=1.22 if factor<.9 else 1.12
        elif conversion>.82: factor*=1.13
        elif conversion>.60: factor*=1.06
        elif conversion<.008 and penetration<.80: factor=min(.72,factor*.65)
        elif conversion<.03 and penetration<.80: factor*=.75
        elif conversion<.16 and penetration<.80: factor*=.89
        elif conversion<.29 and penetration<.74: factor*=.96
        elif penetration>.90: factor*=1.025
    factor=min(3.5,max(.24,factor))
    multipliers[g]=factor
    discounts[g]=round(max(0,p_a-max(9 if day<252 else max(12,.075*min(quota[0],estimates[g]['data']['usage_volume'])),budget(g)*factor)),2)
price_notes.write_text(json.dumps(multipliers))
enterprise_intro={g:round(max(0,p_a-budget(g)*.28),2) for g in groups if 'E' in g}
checked(nm.marketing.set_lead_promotion(by_group={**discounts,**enterprise_intro}))
billing_days=','.join(str(i%30) for i in range(day-6,day+1))
renewals=rows(f"""SELECT c.group_id g,COUNT(*) evaluated,
    SUM(CASE WHEN s.end_day>{day-7} AND s.end_day<={day} THEN 1 ELSE 0 END) lost
    FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE c.customer_type='small'
    AND s.status IN ('subscribed','cancelled') AND s.start_day<={day-7} AND (s.end_day IS NULL OR s.end_day>{day-7})
    AND s.billing_day_mod30 IN ({billing_days}) GROUP BY c.group_id""")
loyalty={}
for r in renewals:
    if r['evaluated']<100 or r['g'] not in discounts: continue
    fraction=r['lost']/r['evaluated']
    if fraction>.48 and (r['g'] in ('S2','D_S05','D_S07') or day>=252):
        current_arpu=actual.get(r['g'],{}).get('mrr',0)/max(1,actual.get(r['g'],{}).get('seats',0))
        loyalty[r['g']]=round(min(28,current_arpu*min(.15,(fraction-.37)*.32)),2)
ongoing={g:round(v+loyalty.get(g,0),2) for g,v in discounts.items()}
renewal_menu={}
if day>=245:
    retention_rates={r['g']:1-r['lost']/max(1,r['evaluated']) for r in renewals}
    menu_path=directory/'renewal-price-factors.json'
    menu_factors=json.loads(menu_path.read_text()) if menu_path.exists() else {}
    trials=['D_S03','D_S06']
    if day>=259: trials.extend(['S1','D_S08'])
    for g in trials:
        factor=menu_factors.get(g,1.0)
