import novamind_api as n
import json
def rows(sql):
    r=n.query(sql)
    if not r.get("success"): raise ValueError(r)
    return r['rows']
def handle_deals(day,prices,unit_costs=None,replacement=None):
    replacement=replacement or {}
    unit_costs=unit_costs or {}
    def menu(g,amount,factors=(.73,1.0,1.26)):
        floors=unit_costs.get(g, [2,5,12])
        if day>=287: factors=(max(1.30,factors[2]*1.27),factors[1],factors[0])
        return [[plan,round(max(floor,amount*factor),2)] for plan,floor,factor in zip("ABC",floors,factors)]
    query=f"""SELECT t.customer_id cid,c.group_id g,t.thread_type typ,t.seat_count seats,t.turn_number turn,t.offer_json offer,
        (SELECT MAX(s.effective_price) FROM subscriptions s WHERE s.customer_id=t.customer_id AND s.status='subscribed') prior_price,
        (SELECT s.plan FROM subscriptions s WHERE s.customer_id=t.customer_id AND s.status='subscribed' ORDER BY s.subscription_id DESC LIMIT 1) prior_plan
        FROM enterprise_turns t JOIN (SELECT thread_id,MAX(message_id) last_id FROM enterprise_turns WHERE day>={day-7} GROUP BY thread_id) latest ON t.message_id=latest.last_id
        JOIN customers c ON t.customer_id=c.customer_id WHERE t.closed=0 AND t.sender IN ('customer','system') AND t.close_reason='' AND t.day>{day-7} ORDER BY t.customer_id, t.message_id"""
    turns=[]
    while True:
        batch=rows(query+f" LIMIT 400 OFFSET {len(turns)}")
        turns.extend(batch)
        if len(batch)<400: break
    deals=[]
    for t in turns:
        tier,price=prices.get(t['g'],('C',45))
        prior=t['prior_price'] or 0
        counter=json.loads(t['offer'] or '{}').get('price')
        if t['typ'] in ('churn_prevention','renewal') and prior:
            price=min(price,max(prior*1.13,replacement.get(t['g'],0),8))
        if t['typ']=='renegotiation' and prior:
            price=max(prior*1.13,min(price,prior*1.75))
        if counter and counter>0:
            price=max(min(price,counter),replacement.get(t['g'],0)*.90)
            if t['typ']=='renegotiation' and prior: price=max(price,prior*1.05)
            offerings=menu(t['g'],price,(.93,.98,1.0))
        else:
            offerings=menu(t['g'],price)
        if day<252 and t['typ']=='renegotiation' and prior and t['prior_plan']=='C' and t['g'] in ('E1','E2','D_E02'):
            mid=max(prior*.86,min(prior*.90,counter or prior))
            offerings=[['A',round(prior*.77,2)],['B',round(mid,2)]]
        deals.append([t['cid'],offerings])
    if day>=105:
        existing=rows(f"""SELECT s.customer_id cid,c.group_id g,s.effective_price price,s.seat_count seats,s.plan p
            FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id
            WHERE c.customer_type='large' AND s.status='subscribed' AND s.start_day<{day-30}
            AND s.customer_id NOT IN (SELECT customer_id FROM enterprise_turns
                WHERE message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id)
                AND closed=0 AND close_reason='')
            AND s.customer_id NOT IN (SELECT customer_id FROM enterprise_turns
                WHERE (day>{day-35} AND thread_type='renegotiation') OR (day>{day-10} AND thread_type='churn_prevention'))
            ORDER BY s.seat_count DESC LIMIT 900""")
        upgrades=[]
        for account in existing:
            plan,target=prices.get(account['g'],('C',45))
            prior=account['price']
