import novamind_api as n
import json
import re
def rows(sql):
    r=n.query(sql)
    if not r.get("success"): raise ValueError(r)
    return r['rows']
def handle_deals(day,prices,unit_costs=None,replacement=None,retention_terms=None,market_shares=None):
    market_shares=market_shares or {}
    retention_terms=retention_terms or {}
    replacement=replacement or {}
    unit_costs=unit_costs or {}
    def menu(g,amount,factors=(.73,1.0,1.26)):
        floors=unit_costs.get(g, [2,5,12])
        if day>=287: factors=(max(1.30,factors[2]*1.27),factors[1],factors[0])
        if day>=357: factors=(factors[0],factors[1],max(1.92,factors[0]*1.30))
        return [[plan,round(max(floor,amount*factor),2)] for plan,floor,factor in zip("ABC",floors,factors)]
    query=f"""SELECT t.customer_id cid,c.group_id g,t.thread_type typ,t.seat_count seats,t.turn_number turn,t.offer_json offer,t.message_text message,
        (SELECT MAX(s.effective_price) FROM subscriptions s WHERE s.customer_id=t.customer_id AND s.status='subscribed') prior_price,
        (SELECT s.plan FROM subscriptions s WHERE s.customer_id=t.customer_id AND s.status='subscribed' ORDER BY s.subscription_id DESC LIMIT 1) prior_plan
        FROM enterprise_turns t JOIN (SELECT thread_id,MAX(message_id) last_id FROM enterprise_turns WHERE day>={day-7} GROUP BY thread_id) latest ON t.message_id=latest.last_id
        JOIN customers c ON t.customer_id=c.customer_id WHERE t.closed=0 AND t.sender IN ('customer','system') AND t.close_reason='' AND t.day>{day-7} ORDER BY t.customer_id, t.message_id"""
    turns=[]
    while True:
        batch=rows(query+f" LIMIT 400 OFFSET {len(turns)}")
        turns.extend(batch)
        if len(batch)<400: break
    deals=[]
    for t in turns:
        tier,price=prices.get(t['g'],('C',45))
        prior=t['prior_price'] or 0
        counter=json.loads(t['offer'] or '{}').get('price')
        if t['typ'] in ('churn_prevention','renewal') and prior:
            price=min(price,max(prior*1.13,replacement.get(t['g'],0),8))
        if t['typ']=='renegotiation' and prior:
            price=max(prior*1.13,min(price,prior*1.75))
        if counter and counter>0:
            price=max(min(price,counter),replacement.get(t['g'],0)*.90)
            if t['typ']=='renegotiation' and prior: price=max(price,prior*1.05)
            offerings=menu(t['g'],price,(.93,.98,1.0))
        else:
            offerings=menu(t['g'],price)
        if day<252 and t['typ']=='renegotiation' and prior and t['prior_plan']=='C' and t['g'] in ('E1','E2','D_E02'):
            mid=max(prior*.86,min(prior*.90,counter or prior))
            offerings=[['A',round(prior*.77,2)],['B',round(mid,2)]]
        if t['typ']=='churn_prevention' and prior and t['g'] in retention_terms:
            exposure,direct_cost,observed_ratio=retention_terms[t['g']]
            if exposure>.25:
                # Open retention talks suspend collections. Price the existing plan to close early.
                discount=.87 if exposure>.48 else .94
                if observed_ratio is not None:
                    discount=min(discount,max(.56,observed_ratio*1.12))
                if t['turn']>2: discount-=.035
                target=min(prior*discount,counter if counter and counter>0 else prior)
                for option in offerings:
                    plan=option[0]
                    if plan==t['prior_plan']:
                        option[1]=round(max(direct_cost[plan],min(option[1],target)),2)
                    elif day<357 and t['prior_plan']=='B' and plan=='C':
                        option[1]=round(max(direct_cost[plan],min(option[1],target*.85)),2)
        if day>=427 and not counter and t['g'] in retention_terms:
            exposure,direct,_=retention_terms[t['g']]
            if t['typ'] in ('renewal','churn_prevention') and prior:
                # A customer unable to use their previous model can take a quality upgrade.
                a=max(direct['A']*1.04,prior*(.93 if exposure>.32 else 1.02))
                c=max(direct['C']*1.08,a+max(5,.70*(direct['C']-direct['A'])))
                targets={'A':a,'C':c}
                for option in offerings:
                    if option[0] in targets: option[1]=round(min(option[1],targets[option[0]]),2)
            elif t['typ']=='new_lead' and market_shares.get(t['g'],1)<.68:
                targets={'A':max(direct['A']*1.28,price*1.24),
                         'C':max(direct['C']*1.28,price*1.48)}
                for option in offerings:
                    if option[0] in targets: option[1]=round(min(option[1],targets[option[0]]),2)
        if day>=357 and counter and t['g'] in retention_terms and t['typ'] in ('new_lead','churn_prevention','renewal'):
            requested=re.search(r'Counter-offer: Plan ([ABC])',t['message'])
